import{_ as i,o as e,c as o,a2 as s}from"./chunks/framework.CqpfiAoK.js";const p=JSON.parse('{"title":"Sistema Judiciário e Mecanismo de Decisão","description":"","frontmatter":{},"headers":[],"relativePath":"pt/0048-司法体系与裁决机制.md","filePath":"pt/0048-司法体系与裁决机制.md"}'),t={name:"pt/0048-司法体系与裁决机制.md"};function r(d,a,n,c,l,u){return e(),o("div",null,[...a[0]||(a[0]=[s('<h1 id="sistema-judiciario-e-mecanismo-de-decisao" tabindex="-1">Sistema Judiciário e Mecanismo de Decisão <a class="header-anchor" href="#sistema-judiciario-e-mecanismo-de-decisao" aria-label="Permalink to &quot;Sistema Judiciário e Mecanismo de Decisão&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Projeto</th><th>Conteúdo</th></tr></thead><tbody><tr><td>Número do documento</td><td>48</td></tr><tr><td>Módulo</td><td>Sistema Jurídico e Estrutura de Governança</td></tr><tr><td>Palavras-chave principais</td><td>Tribunal Simbiótico, Independência Judiciária, Mecanismo de Decisão, Julgamento Inter-Racial, Revisão de Inconstitucionalidade</td></tr></tbody></table><h2 id="i-posicao-e-principios-do-sistema-judiciario" tabindex="-1">I. Posição e Princípios do Sistema Judiciário <a class="header-anchor" href="#i-posicao-e-principios-do-sistema-judiciario" aria-label="Permalink to &quot;I. Posição e Princípios do Sistema Judiciário&quot;">​</a></h2><p>O sistema judiciário é um pilar importante da estrutura de governança da civilização simbiótica de âncoras, paralelo ao poder legislativo (Conselho de Âncoras) e ao poder executivo (Comitê Executivo Simbiótico), exercendo independentemente o poder de julgamento. A 《Constituição Simbiótica》 estabelece a estrutura de governança de &quot;separação e equilíbrio dos três poderes&quot;, e o sistema judiciário é a linha final de defesa para manter a dignidade constitucional, proteger os direitos de todos os seres e resolver disputas sociais.</p><p>O sistema judiciário de Hengyuanzhou estabelece os seguintes princípios fundamentais:</p><table tabindex="0"><thead><tr><th>Princípio</th><th>Conteúdo</th></tr></thead><tbody><tr><td>Princípio da Independência Judiciária</td><td>Os tribunais exercem independentemente o poder de julgamento de acordo com a lei, sem interferência de órgãos administrativos, organizações sociais e indivíduos</td></tr><tr><td>Princípio da Justiça Judiciária</td><td>As atividades de julgamento baseiam-se nos fatos e tomam a lei como critério, garantindo a justiça processual e a justiça substantiva</td></tr><tr><td>Princípio da Publicidade Judiciária</td><td>As atividades de julgamento são realizadas publicamente de acordo com a lei, os documentos judiciais são publicados e aceitam a supervisão social</td></tr><tr><td>Princípio da Igualdade de Todas as Raças</td><td>Todos os seres são iguais perante a justiça, e a aplicação da lei não distingue raça, nível de cultivo ou origem</td></tr><tr><td>Princípio da Conveniência Judiciária</td><td>Os serviços judiciários devem ser convenientes para todos os seres, reduzir os custos processuais e fornecer múltiplas vias de resolução de disputas</td></tr><tr><td>Princípio da Decisão Final</td><td>É aplicado o sistema de duas instâncias como instância final, e a decisão final tem efeito terminativo, mantendo a autoridade judiciária</td></tr></tbody></table><h2 id="ii-sistema-organizacional-dos-tribunais" tabindex="-1">II. Sistema Organizacional dos Tribunais <a class="header-anchor" href="#ii-sistema-organizacional-dos-tribunais" aria-label="Permalink to &quot;II. Sistema Organizacional dos Tribunais&quot;">​</a></h2><p>O sistema organizacional dos tribunais da civilização simbiótica de âncoras é dividido em quatro níveis, aplicando o sistema de duas instâncias como instância final:</p><table tabindex="0"><thead><tr><th>Nível</th><th>Nome do Tribunal</th><th>Âmbito de Competência</th><th>Funções Principais</th></tr></thead><tbody><tr><td>Primeiro Nível</td><td>Tribunal Simbiótico de Base</td><td>Condado/Plano Pequeno</td><td>Julgar casos civis, criminais e administrativos de primeira instância, resolver disputas simples</td></tr><tr><td>Segundo Nível</td><td>Tribunal Simbiótico Regional</td><td>Cidade/Região/Plano Médio</td><td>Julgar casos graves de primeira instância e casos de apelação contra sentenças do tribunal de base</td></tr><tr><td>Terceiro Nível</td><td>Tribunal Simbiótico de Plano</td><td>Plano Grande/Grupo de Planos</td><td>Julgar casos especialmente graves de primeira instância e casos de apelação contra sentenças do tribunal regional</td></tr><tr><td>Quarto Nível</td><td>Supremo Tribunal Simbiótico</td><td>Todo o Universo</td><td>Julgar casos constitucionais de primeira instância, casos de apelação contra sentenças do tribunal de plano, e revisão de inconstitucionalidade</td></tr></tbody></table><p>Além disso, tribunais especiais são estabelecidos conforme necessário:</p><ul><li><strong>Tribunal de Disputas de Cultivo</strong>: Especializado em julgar disputas de recursos de cultivo, indenização por danos de cultivo, controvérsias éticas de cultivo, etc.</li><li><strong>Tribunal Inter-Racial</strong>: Especializado em julgar disputas envolvendo diferentes raças, equipado com juízes de cada raça.</li><li><strong>Tribunal Comercial de Plano</strong>: Especializado em julgar disputas comerciais inter-planos e casos antimonopólio.</li><li><strong>Tribunal de Seres Estranhos</strong>: Especializado em julgar casos especiais envolvendo seres estranhos, energias estranhas e corpos de substituição escura.</li></ul><h2 id="iii-sistema-de-juizes" tabindex="-1">III. Sistema de Juízes <a class="header-anchor" href="#iii-sistema-de-juizes" aria-label="Permalink to &quot;III. Sistema de Juízes&quot;">​</a></h2><p>Os juízes são os exercitores do poder judiciário, e sua qualidade e independência estão diretamente relacionadas à justiça judiciária:</p><ol><li><strong>Condições de Nomeação de Juízes</strong>: Os juízes devem ter boa conduta, sólida formação jurídica e rica experiência prática, e os juízes de raças estrangeiras também devem estar familiarizados com a cultura e características fisiológicas de sua própria raça.</li><li><strong>Processo de Seleção de Juízes</strong>: Os juízes são nomeados por um comitê independente de seleção de juízes e nomeados pelo Conselho de Âncoras, garantindo a justiça e profissionalismo do processo de seleção.</li><li><strong>Garantia de Identidade dos Juízes</strong>: Os juízes não podem ser demitidos, rebaixados, dispensados ou punidos sem motivos legais e sem processo legal, garantindo que os juízes possam julgar independentemente.</li><li><strong>Sistema de Abstenção de Juízes</strong>: Os juízes que tiverem interesse nas partes do caso ou no resultado do caso devem se abster e não podem participar do julgamento do caso.</li><li><strong>Sistema de Punição de Juízes</strong>: Os juízes que praticarem corrupção, suborno, fraude, julgamento arbitrário, etc., serão punidos de acordo com a lei, e os que constituírem crime serão追究 responsabilidade criminal.</li><li><strong>Cota de Juízes de Raças Estrangeiras</strong>: Os tribunais de todos os níveis devem equipar uma certa proporção de juízes de raças estrangeiras, garantindo que o julgamento possa levar em conta a cultura e o conhecimento jurídico de cada raça.</li></ol><h2 id="iv-processo-processual" tabindex="-1">IV. Processo Processual <a class="header-anchor" href="#iv-processo-processual" aria-label="Permalink to &quot;IV. Processo Processual&quot;">​</a></h2><h3 id="_1-processo-civil" tabindex="-1">(1) Processo Civil <a class="header-anchor" href="#_1-processo-civil" aria-label="Permalink to &quot;(1) Processo Civil&quot;">​</a></h3><p>O processo civil aplica o princípio de &quot;não há julgamento sem queixa&quot;, e o processo inclui:</p><ol><li><strong>Queixa e Aceitação</strong>: O autor apresenta uma queixa ao tribunal competente, e o tribunal decide após revisão se aceita ou não.</li><li><strong>Preparação Antes do Julgamento</strong>: O tribunal entrega uma cópia da queixa ao réu, organiza a troca de evidências e determina os pontos de disputa.</li><li><strong>Julgamento em Audiência</strong>: Investigação judicial, debate judicial, declaração final das partes, com mediação prioritária.</li><li><strong>Sentença e Execução</strong>: O tribunal profere sentença de acordo com a lei, e as partes insatisfeitas podem apelar dentro do prazo legal. A sentença efetiva é executada coercitivamente pelo órgão executivo.</li></ol><h3 id="_2-processo-criminal" tabindex="-1">(2) Processo Criminal <a class="header-anchor" href="#_2-processo-criminal" aria-label="Permalink to &quot;(2) Processo Criminal&quot;">​</a></h3><p>O processo criminal aplica o princípio da &quot;presunção de inocência&quot;, e o processo inclui:</p><ol><li><strong>Arquivamento e Investigação</strong>: O órgão investigador arquiva e investiga o crime, coleta evidências e toma medidas coercitivas.</li><li><strong>Revisão e Queixa</strong>: O órgão de acusação revisa os resultados da investigação e decide se apresenta queixa pública.</li><li><strong>Julgamento</strong>: O tribunal realiza audiência, as partes de acusação e defesa apresentam e questionam evidências, e o tribunal profere sentença de acordo com a lei.</li><li><strong>Execução</strong>: A sentença efetiva é executada pelo órgão executivo, incluindo a execução da pena e a execução da indenização civil acessória.</li></ol><h3 id="_3-processo-administrativo" tabindex="-1">(3) Processo Administrativo <a class="header-anchor" href="#_3-processo-administrativo" aria-label="Permalink to &quot;(3) Processo Administrativo&quot;">​</a></h3><p>Cidadãos, pessoas jurídicas ou outras organizações que considerem que o ato administrativo de um órgão administrativo violou seus direitos legais têm o direito de apresentar processo administrativo ao tribunal. O processo administrativo aplica a &quot;inversão do ônus da prova&quot;, e o órgão administrativo réu deve assumir o ônus da prova sobre a legalidade de seu ato administrativo.</p><h3 id="_4-processo-constitucional" tabindex="-1">(4) Processo Constitucional <a class="header-anchor" href="#_4-processo-constitucional" aria-label="Permalink to &quot;(4) Processo Constitucional&quot;">​</a></h3><p>Todos os seres que considerem que seus direitos constitucionais básicos foram violados e que esgotaram outras vias de reparação podem diretamente apresentar processo constitucional ao Supremo Tribunal Simbiótico com base na Constituição. O processo constitucional é a via final de reparação para proteger os direitos constitucionais.</p><h2 id="v-mecanismo-de-resolucao-de-disputas-multiplo" tabindex="-1">V. Mecanismo de Resolução de Disputas Múltiplo <a class="header-anchor" href="#v-mecanismo-de-resolucao-de-disputas-multiplo" aria-label="Permalink to &quot;V. Mecanismo de Resolução de Disputas Múltiplo&quot;">​</a></h2><p>Para reduzir a carga judiciária e melhorar a eficiência da resolução de disputas, o Estado estabelece um mecanismo de resolução de disputas múltiplo:</p><table tabindex="0"><thead><tr><th>Mecanismo</th><th>Âmbito de Aplicação</th><th>Efeito</th></tr></thead><tbody><tr><td>Negociação e Acordo</td><td>Todas as disputas civis</td><td>As partes cumprem voluntariamente, sem força executória coercitiva</td></tr><tr><td>Mediação Popular</td><td>Disputas populares, disputas de vizinhança</td><td>O acordo de mediação tem força executória coercitiva após confirmação judicial pelo tribunal</td></tr><tr><td>Mediação Administrativa</td><td>Disputas administrativas, disputas de indenização civil</td><td>O acordo de mediação tem efeito contratual</td></tr><tr><td>Arbitragem</td><td>Disputas comerciais, disputas trabalhistas</td><td>A sentença arbitral tem força executória coercitiva, com arbitragem única e final</td></tr><tr><td>Decisão Judicial</td><td>Todas as disputas</td><td>A sentença final tem força executória coercitiva terminativa</td></tr></tbody></table><p>O Estado incentiva as partes a priorizar a resolução de disputas por meio não processual, e os tribunais também devem realizar mediação durante o processo.</p><h2 id="vi-sistema-de-revisao-de-inconstitucionalidade" tabindex="-1">VI. Sistema de Revisão de Inconstitucionalidade <a class="header-anchor" href="#vi-sistema-de-revisao-de-inconstitucionalidade" aria-label="Permalink to &quot;VI. Sistema de Revisão de Inconstitucionalidade&quot;">​</a></h2><p>A revisão de inconstitucionalidade é um sistema importante para o sistema judiciário manter a autoridade constitucional:</p><ol><li><strong>Órgão de Revisão</strong>: O Supremo Tribunal Simbiótico é o único órgão de revisão de inconstitucionalidade, estabelecendo uma câmara de julgamento constitucional especializada em revisão de inconstitucionalidade.</li><li><strong>Âmbito de Revisão</strong>: Se leis, regulamentos administrativos, regulamentos locais, regulamentos autônomos, interpretações judiciais e outros documentos normativos violam a Constituição.</li><li><strong>Início da Revisão</strong>: Pode ser iniciado ativamente pelo tribunal durante o julgamento do caso, ou por solicitação de revisão apresentada por todos os seres, organizações ou órgãos estatais.</li><li><strong>Efeito da Revisão</strong>: Os documentos normativos considerados inconstitucionais após revisão são inválidos a partir da data de publicação e não podem mais ser usados como base para julgamento.</li><li><strong>Critério de Revisão</strong>: Baseado no texto constitucional e nos princípios constitucionais, levando em conta a estabilidade do sistema jurídico e a adaptabilidade da Constituição.</li></ol><h2 id="vii-garantia-e-supervisao-judiciaria" tabindex="-1">VII. Garantia e Supervisão Judiciária <a class="header-anchor" href="#vii-garantia-e-supervisao-judiciaria" aria-label="Permalink to &quot;VII. Garantia e Supervisão Judiciária&quot;">​</a></h2><ul><li><strong>Garantia de Verbas Judiciárias</strong>: As verbas dos tribunais são garantidas separadamente pela acumulação pública, não sendo controladas por órgãos administrativos locais, garantindo a base econômica da independência judiciária.</li><li><strong>Informatização Judiciária</strong>: Utilizar tecnologia de comunicação inter-planos para estabelecer um sistema de informação judiciária,实现 a informatização de todo o processo de arquivamento, julgamento e execução, melhorando a eficiência judiciária.</li><li><strong>Supervisão Judiciária</strong>: O Comitê de Supervisão de Âncoras supervisiona as atividades judiciais, e o público e a mídia podem realizar supervisão de opinião pública sobre as atividades judiciais, mas não podem interferir na independência do julgamento.</li><li><strong>Assistência Judiciária</strong>: Fornecer assistência jurídica e redução ou isenção de custos processuais para partes com dificuldades econômicas, garantindo que não percam a oportunidade de reparação judicial por razões econômicas.</li></ul><h2 id="conclusao" tabindex="-1">Conclusão <a class="header-anchor" href="#conclusao" aria-label="Permalink to &quot;Conclusão&quot;">​</a></h2><p>O sistema judiciário é a garantia final do Estado de Direito da civilização simbiótica de âncoras. Ao estabelecer um sistema de tribunais de quatro níveis, aplicar a independência judiciária, estabelecer um mecanismo de resolução de disputas múltiplo e um sistema de revisão de inconstitucionalidade, ele garante que a lei seja aplicada de forma justa, que os direitos de todos os seres sejam efetivamente reparados, e fortalece a linha de defesa do Estado de Direito para o progresso comum de todas as raças.</p><h2 id="documentos-relacionados" tabindex="-1">Documentos relacionados <a class="header-anchor" href="#documentos-relacionados" aria-label="Permalink to &quot;Documentos relacionados&quot;">​</a></h2><ul><li>40-共生宪法总纲 (Princípios Gerais da Constituição Simbiótica)</li><li>49-治理框架与权力制衡 (Estrutura de Governança e Equilíbrio de Poderes)</li><li>58-双魂伦理准则 (Código Ético de Duas Almas)</li><li>03-共生文明宪章 (Carta da Civilização Simbiótica)</li></ul>',38)])])}const v=i(t,[["render",r]]);export{p as __pageData,v as default};
